/** "What changed" data: types and read-side helpers. The files are generated by scripts/refresh/diff.ts. */
export const CHANGE_TYPES = [
  "price_changed",
  "price_added",
  "price_removed",
  "version_added",
  "version_withdrawn",
  "availability_changed",
  "range_changed",
  "warranty_changed",
] as const;
export type ChangeType = (typeof CHANGE_TYPES)[number];
export const CHANGE_TYPE_LABELS: Record<ChangeType, string> = {
  price_changed: "Price changed",
  price_added: "Price now published",
  price_removed: "Price no longer published",
  version_added: "New versions on sale",
  version_withdrawn: "Versions no longer on sale",
  availability_changed: "Availability changed",
  range_changed: "Range changed",
  warranty_changed: "Warranty changed",
};
export type ChangeValue = {
  value: string | number | null;
  unit: string;
  /** Measurement or price basis as recorded, e.g. "Before on-road costs". */
  basis: string;
};
export type ChangeEntry = {
  type: ChangeType;
  versionId: string;
  brand: string;
  /** Brand, model and trim as a buyer reads it. */
  vehicle: string;
  /** Catalogue family and slug, for the version page link. */
  family: string;
  slug: string;
  field: string;
  before: ChangeValue | null;
  after: ChangeValue | null;
  beforeDate: string | null;
  afterDate: string | null;
  sourceIds: string[];
};
export type ChangeSource = {
  id: string;
  url: string;
  title: string;
  publisher: string;
  accessed_date: string;
};
export type ChangesMonth = {
  schema: "roadmark-changes-v1";
  month: string;
  generator: "scripts/refresh/diff.ts";
  before: { asOf: string; sha256: string };
  after: { asOf: string; sha256: string };
  counts: Record<ChangeType, number>;
  sources: ChangeSource[];
  changes: ChangeEntry[];
};
const typeRank = new Map<string, number>(CHANGE_TYPES.map((type, index) => [type, index]));
/** Entries grouped by type (plan order) then brand, as the page and feeds list them. */
export function groupChanges(changes: readonly ChangeEntry[]) {
  const groups: {
    type: ChangeType;
    brands: { brand: string; entries: ChangeEntry[] }[];
  }[] = [];
  const ordered = [...changes].sort(
    (a, b) =>
      typeRank.get(a.type)! - typeRank.get(b.type)! ||
      a.brand.localeCompare(b.brand) ||
      a.vehicle.localeCompare(b.vehicle) ||
      a.field.localeCompare(b.field),
  );
  for (const entry of ordered) {
    let group = groups.find((g) => g.type === entry.type);
    if (!group) groups.push((group = { type: entry.type, brands: [] }));
    let brand = group.brands.find((b) => b.brand === entry.brand);
    if (!brand) group.brands.push((brand = { brand: entry.brand, entries: [] }));
    brand.entries.push(entry);
  }
  return groups;
}
/** Months newest first. */
export function sortMonthsNewestFirst<T extends { month: string }>(
  months: readonly T[],
): T[] {
  return [...months].sort((a, b) => b.month.localeCompare(a.month));
}
export function formatChangeValue(value: ChangeValue | null): string {
  if (!value || value.value === null || value.value === "") return "—";
  const number =
    typeof value.value === "number"
      ? value.unit === "AUD"
        ? `A$${value.value.toLocaleString("en-AU")}`
        : `${value.value.toLocaleString("en-AU")}${value.unit ? ` ${value.unit}` : ""}`
      : `${value.value}`;
  return value.basis ? `${number} (${value.basis})` : number;
}
export const monthLabel = (month: string) => {
  const [year, m] = month.split("-").map(Number);
  return new Date(Date.UTC(year, m - 1, 1)).toLocaleString("en-AU", {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
};
const FIELD_LABELS: Record<string, string> = {
  price_aud: "Price",
  promotional_driveaway_aud: "Promotional driveaway price",
  published_driveaway_aud: "Published driveaway price",
  range_km: "Range",
  warranty: "Vehicle warranty",
  battery_warranty: "Battery warranty",
  availability: "Availability",
  version: "Version",
};
export const fieldLabel = (field: string) =>
  FIELD_LABELS[field] ??
  field.replaceAll("_", " ").replace(/^./, (c) => c.toUpperCase());
const STATE_WORDS: Record<string, string> = {
  current_or_order_listed: "Current listing",
  outgoing: "Older / outgoing version",
  announced_provisional: "Announced / provisional",
  not_current: "Not currently available",
};
const ORDER_WORDS: Record<string, string> = {
  accepting_order_requests_advertised: "order requests advertised",
  accepting_orders: "orders open",
  accepting_orders_advertised: "orders advertised as open",
  preorder: "pre-orders",
  not_accepting_orders: "not taking orders",
  listed_unconfirmed: "listed, orders unconfirmed",
  unverified: "orders unconfirmed",
};
/** "state; orders: x; stock: y" (as diff.ts writes it) in buyer words. Never claims physical stock. */
export function describeAvailability(value: string | number | null): string {
  if (typeof value !== "string") return "—";
  const [state = "", orders = "", stock = ""] = value.split("; ");
  const orderKey = orders.replace(/^orders: /, "");
  const stockKey = stock.replace(/^stock: /, "");
  return [
    STATE_WORDS[state] ?? state.replaceAll("_", " "),
    ORDER_WORDS[orderKey] ?? orderKey.replaceAll("_", " "),
    stockKey === "new_stock_listed" ? "new stock advertised" : "",
  ]
    .filter(Boolean)
    .join(" · ");
}
/** A buyer-readable sentence for an entry, shared by the page and the feeds. */
export function describeChange(entry: ChangeEntry): string {
  const text = (v: ChangeValue | null) =>
    entry.field === "availability" || entry.field === "version"
      ? v
        ? describeAvailability(v.value)
        : "—"
      : formatChangeValue(v);
  if (entry.type === "version_added")
    return `New on sale: ${text(entry.after)}`;
  if (entry.type === "version_withdrawn")
    return `No longer on sale (was: ${text(entry.before)})`;
  if (entry.type === "price_added") return `${fieldLabel(entry.field)}: now ${text(entry.after)}`;
  if (entry.type === "price_removed") return `${fieldLabel(entry.field)}: was ${text(entry.before)}, no longer shown`;
  return `${fieldLabel(entry.field)}: ${text(entry.before)} → ${text(entry.after)}`;
}
export const entryAnchor = (month: string, entry: ChangeEntry) =>
  `${month}-${entry.type}-${entry.versionId}-${entry.field}`.replace(
    /[^A-Za-z0-9_-]/g,
    "-",
  );
